    "content": "不清楚你是不是也曾经有过这样的感受。 和某个人待在一块儿的时候，明明完全没做啥繁重的体力活，心却一直悬着放不下来。开口前多思量，行事时多留意，就怕哪句话说得不妥当，哪件事做得不到位。 明明是谈恋爱，却像在打一场永远不能输的仗，越处越累。&nbsp; 不少人刚一开口最先问的问题就是：他究竟爱不爱我？ 其实爱不爱，真没那么重要。要判断一段感情的状态好不好，没必要总纠结爱不爱这件事，最直接的判断标准就是你相处起来累不累。疲惫本身，就是不会弄虚作假的真实回应。 我之前有过一段恋爱经历，现在回想起来，还是会有种憋闷得透不过气…"
