    "description": "据总台报道，8月30日，伊朗最高领袖穆杰塔巴·哈梅内伊发表声明说，西亚地区国家的统治者，必须认清其真正的敌人，了解他们的阴谋，并与之对抗。解决地区问题的出路在于团结一致、友谊长存、携手共进。美国和以色列是这种团结与友谊的死敌，他们不仅是伊朗和抵抗阵线的敌人，也是包括西亚和北非国家在内的敌人。",
