    "author": "程楠",
    "description": "新华社兰州8月30日电（记者程楠）第九届海峡两岸西王母文化交流活动30日在甘肃省平凉市泾川县举行，来自海峡两岸的400多名嘉宾同聚一堂，共祭西王母。 上午10时许，谒礼仪式在泾川西王母宫举行。现场礼乐恢弘，钟鼓回荡。恭读谒礼文之后，两岸与会嘉宾依次敬献花篮、行参拜礼。随后，人群有序进入西王母大殿瞻仰。 在人群中，记者遇到了来自台湾新竹的彭祥轩。他今年27岁，第一次在大陆参加两岸西王母文化交流活动。“我的家人在台湾，都崇尚西王母。大陆是西…",
    "content": "新华社兰州8月30日电（记者程楠）第九届海峡两岸西王母文化交流活动30日在甘肃省平凉市泾川县举行，来自海峡两岸的400多名嘉宾同聚一堂，共祭西王母。 上午10时许，谒礼仪式在泾川西王母宫举行。现场礼乐恢弘，钟鼓回荡。恭读谒礼文之后，两岸与会嘉宾依次敬献花篮、行参拜礼。随后，人群有序进入西王母大殿瞻仰。 在人群中，记者遇到了来自台湾新竹的彭祥轩。他今年27岁，第一次在大陆参加两岸西王母文化交流活动。“我的家人在台湾，都崇尚西王母。大陆是西王母文化的发祥地，能参加这次活动，我非常开心。”彭祥轩说，目前他已在上海工作，大…"
