    "pub_date": "2026-08-30 17:57:27",
    "author": "",
    "description": "36氪获悉，8月30日，沐曦股份披露2026年半年度报告。上半年公司实现营业收入13.24亿元，同比增长44.67%;归母净利润6.12亿元，实现扭亏。分季度看，二季度实现收入7.62亿元，单季扣非归母净利润0.54亿元,环比亦由亏转盈。上半年毛利率57.2%，同比提升1.1个百分点。公告称，随着公司产品及服务持续获得下游客户的广泛认可与采购，GPU产品出货量显著提升，带动收入规模较上年同期实现显著增加。",
