    "content": "新华社厦门8月30日电（记者郑良）8月30日，厦门市联合调查组就媒体报道的“厦门一公司使用敌敌畏为餐饮门店消杀问题”发布通报，事件共有6名嫌疑人被刑拘。 通报称，经调查，厦门绿林森环境科技有限公司相关行为涉嫌违法违规，性质十分恶劣。公安机关已对法定代表人庄某臣、股东曾某鸣、业务培训主管李某等6名犯罪嫌疑人依法刑事拘留，案件正在进一步侦办中。 通报表示，经全面排查该公司提供消杀服务的经营主体，并委托具有检验检测资质的机构对场所环境、餐厨用具等进行检测，结果显示相关指标符合安全标准。厦门市将深刻汲取教训，举一反三、完善…"
