    "author": "",
    "description": "",
    "content": "快科技8月30日消息，近日，由北航宇航学院空间动力实验室携手商业航天企业奔熠科技联合研制的“冰焰飞梭”铝冰探空火箭，近期于内蒙古巴彦淖尔完成首次飞行试验。 从传回的遥测数据来看，火箭最大飞行高度达到5276米，本次试飞任务顺利收官。这次试飞不仅是亚洲范围内铝冰火箭的首次实际飞行验证，更一举刷新该技术路线全球公开飞行高度纪录。 铝冰火箭的核心亮点在于它特殊的推进剂。这种燃料主要由铝粉与水混合冷冻制成，而铝元素和水冰资源在月球表面都能够找到。 这项技术的核心构想，就是探索未来直接利用月球本土资源制备火箭燃料，不必完全依…"
