    "content": "新华社尼泊尔努瓦果德8月30日电 现场直击｜尼泊尔泥石流灾区见闻 新华社记者邹学冕 刘天 胥舒骜 在位于尼泊尔北部山区的巴格马蒂省努瓦果德县，一大片灰白色泥沙沿河谷铺展开来，一幢幢房屋陷入泥中。断裂的电线杆横在路旁，电线与树枝、布条和生活用品缠绕在一起，空气中不时飘来刺鼻气味。 当地居民桑托什·塔帕告诉记者，这里是比杜尔小镇，约有300户家庭，超过千人祖祖辈辈生活在此。26日上午，一场泥石流席卷而来，导致周围的巴格马蒂省拉苏瓦、努瓦果德和塔丁3个县受灾，大量人员伤亡和基础设施遭破坏。 记者抵达时，推土机已在镇上清出…"
