    "author": "",
    "description": "36氪获悉，东航物流8月30日披露半年报，2026年上半年，公司实现营业收入142.53亿元，同比增长26.62%；实现归属于上市公司股东的净利润14.18亿元，同比增长10.05%；基本每股收益0.89元。",
    "content": "36氪获悉，东航物流8月30日披露半年报，2026年上半年，公司实现营业收入142.53亿元，同比增长26.62%；实现归属于上市公司股东的净利润14.18亿元，同比增长10.05%；基本每股收益0.89元。"
