    "content": "IT之家 8 月 30 日消息，8 月 26 日，西藏日喀则市吉隆口岸区域发生重大灾情，造成沿线通信设施严重受损，极大影响应急救援、道路疏通等各项抢险救灾工作有序推进。 中国联通今日宣布， 8 月 30 日 13 时 30 分，吉隆口岸首个紧邻国门的应急基站正式开通投用 ， 信号覆盖最远可达国门 1.2 公里 ，成功补齐边境前沿通信盲区短板，同时通过与电信开展网络共享、与移动实施异网漫游， 向移动、电信用户提供网络服务 ，积极解决抢险区域网络薄弱问题，为现场救援、道路抢通、物资运输及一线作业人员提供稳定可靠的通信支…"
