    "author": "",
    "description": "36氪获悉，赤峰黄金发布2026年半年度报告，实现营业收入70.18亿元，同比增长33.11%；归属于上市公司股东的净利润17.32亿元，同比增长56.5%。业绩增长主要受益于黄金价格高位运行及全球化布局优势。小财注：公司Q2净利润7.44亿，之前预告区间为7.12亿-7.92亿，Q1净利润9.88亿，据此计算，Q2净利润环比下降24%。",
