    "description": "8月30日，复旦2026级新生报到。一位从重庆来的新生说，父亲在沪打工20年，“第一个动力就是离爸爸近一点”。父亲说：“他终于达到他梦想，我也心满意足了。”",
    "content": "8月30日，复旦2026级新生报到。一位从重庆来的新生说，父亲在沪打工20年，“第一个动力就是离爸爸近一点”。父亲说：“他终于达到他梦想，我也心满意足了。”"
