    "description": "36氪获悉，中国黄金8月30日披露半年报，公司上半年实现营业收入249亿元，同比下降19.93%；归属于上市公司股东的净利润2.79亿元，同比下降12.35%；基本每股收益0.17元/股。公司拟向全体股东每10股派发现金股利0.92元（含税）。报告期内，公司业绩主要受到黄金产品销量同比下降、营业成本及各项费用变动，以及存货金额增加和经营性应付项目减少等因素的影响。",
    "content": "36氪获悉，中国黄金8月30日披露半年报，公司上半年实现营业收入249亿元，同比下降19.93%；归属于上市公司股东的净利润2.79亿元，同比下降12.35%；基本每股收益0.17元/股。公司拟向全体股东每10股派发现金股利0.92元（含税）。报告期内，公司业绩主要受到黄金产品销量同比下降、营业成本及各项费用变动，以及存货金额增加和经营性应付项目减少等因素的影响。"
