    "description": "哈萨克斯坦凤凰24通讯社新闻服务主任伊利亚斯说，几年前在中国留学时往阿拉木图寄包裹，有时需要一个多月才能收到。他与新华社记者一起来到中国·西安哈萨克斯坦码头，亲眼见证物流变革。 中国·西安哈萨克斯坦码头位于哈萨克斯坦第一大城市阿拉木图，于2025年6月10日投入使用。码头以西安国际港中亚班列为依托，对中亚国家的进出口和过境货物流进行多模式整合，为商品过境和出口提供集装箱交易、到发、储存等全方位集装箱运输服务。 综合新华社记者报道 新华社…",
    "content": "哈萨克斯坦凤凰24通讯社新闻服务主任伊利亚斯说，几年前在中国留学时往阿拉木图寄包裹，有时需要一个多月才能收到。他与新华社记者一起来到中国·西安哈萨克斯坦码头，亲眼见证物流变革。 中国·西安哈萨克斯坦码头位于哈萨克斯坦第一大城市阿拉木图，于2025年6月10日投入使用。码头以西安国际港中亚班列为依托，对中亚国家的进出口和过境货物流进行多模式整合，为商品过境和出口提供集装箱交易、到发、储存等全方位集装箱运输服务。 综合新华社记者报道 新华社音视频部制作"
