    "description": "8月28日，在赴比什凯克对吉尔吉斯斯坦进行国事访问并出席2026年上海合作组织峰会前夕，习近平主席在吉尔吉斯斯坦媒体发表的署名文章中指出，中吉传统友谊是两国共同的宝贵财富。要深化两国文化、旅游、艺术、媒体、智库、青年、考古、卫生等交流合作，全面拉紧人文纽带。鼓励更多青年学子赴对方国家留学深造，支持地方交流走深走实。讲好中吉友好交往和互利合作故事，持续筑牢民心相通根基。",
