    "content": "V2EX 的朋友们好，我是「白纸日历」的开发者。 它目前免费、无广告，也有用户反馈它的界面和功能比 macOS 自带日历更好用。 我把它定位成一款为中国用户定制的中文日历，把农历、节气、节假日、调休和日程放进 Mac 菜单栏。 我做这个应用的原因很简单：在 Mac 上，我每天都会确认几次日期、星期、农历、调休和当天安排。可是这些信息分散在菜单栏、系统日历、提醒事项和节假日网页里。为了回答一个很小的问题，往往要连续打开几个地方。 于是我做了「白纸日历」：让它安静地待在菜单栏，需要时点一下，今天是什么日子、这个月怎么放…"
