    "content": "在吉尔吉斯斯坦首都比什凯克，不少老旧街道都经历了修复“焕新”。 2015年至2022年，中吉两国合作推进比什凯克市政路网改造工程，共改造135条街道，总长211公里。2025年底，该工程通过质保期，正式交付，惠及百万市民。 37岁的埃尔梅克·阿什拉利耶夫是众多本地建设者中的一员。家乡的变化肉眼可见，他的自豪发自内心。 修路架桥的过程中，中吉合作项目培养了一批本土工程人才，也吸纳了不少当地居民就业。路越修越远，两国人民的相互了解也在不断加深。 路通了，灯亮了，心暖了。中吉两国的合作故事，仍在继续。 在比什凯克的吉尔吉…"
