    "description": "中新网圣保罗8月30日电(记者 林春茵)当地时间29日，巴中经贸交流中心医学培训中心在巴西圣保罗启动常态化急救公益培训。首批20余名学员来自当地华社、中资企业、孔子学院等机构。随着新一轮强厄尔尼诺临近，巴西正从医疗救援体系建设到公众防灾急救培训等多个层面加强准备，这场面向普通民众的培训也是其中一个缩影。",
