    "content": "新华社东京8月30日电（记者梁晨 陈泽安）受锋面和暖湿气流影响，日本福井县30日遭遇强降雨天气。日本气象厅当天向该县福井市、大野市和胜山市发布最高级别警报，呼吁民众确保人身安全。 日本气象厅说，截至30日5时40分，胜山市和坂井市春江町24小时降雨量分别达到292毫米和282.5毫米，均创有观测记录以来最高值。受强降雨影响，福井县多条高速公路和国道部分路段封闭，多条铁路停运。 另据日本媒体报道，福井市、大野市和胜山市多地出现道路积水、山体滑坡和河流泛滥，多人因暴雨受伤，部分房屋进水，有车辆因积水受困。三市已向当地居…"
