    "author": "蒋梦辰,黄韬铭",
    "description": "新华社拉萨8月30日电（记者蒋梦辰、黄韬铭）8月26日，因尼泊尔一侧发生泥石流灾害，造成西藏日喀则市吉隆县吉隆口岸重大人员伤亡、失联。 泥石流灾害成因是什么？遭遇泥石流如何科学避险？如何防范次生灾害？记者就此采访了有关专家。 应急管理部国家自然灾害防治研究院科技委员会主任刘传正介绍，泥石流是土石和水的混合体向前高速流动的现象，它可以流动十几公里远。这种灾害主要是由强降雨引发，但如果这个地区此前发生过地震，地震破坏了山体，表面难以察觉，再…",
    "content": "新华社拉萨8月30日电（记者蒋梦辰、黄韬铭）8月26日，因尼泊尔一侧发生泥石流灾害，造成西藏日喀则市吉隆县吉隆口岸重大人员伤亡、失联。 泥石流灾害成因是什么？遭遇泥石流如何科学避险？如何防范次生灾害？记者就此采访了有关专家。 应急管理部国家自然灾害防治研究院科技委员会主任刘传正介绍，泥石流是土石和水的混合体向前高速流动的现象，它可以流动十几公里远。这种灾害主要是由强降雨引发，但如果这个地区此前发生过地震，地震破坏了山体，表面难以察觉，再经过强降雨，有可能发生大规模崩塌、滑坡和塌陷。 成灾前，应如何做好防范？拉萨青锋…"
